/**
 * The regret harness in theme mode: every query of a theme catalogue against the theme benchmark's store (14.6M quads
 * for the medical theme), every admitted strategy at the top decision interleaved for a warm-up window and then exactly
 * {@code rounds} runs each; the fastest run counts. Writes the same TSV as the FOAF harness.
 *
 * Enabled with {@code -Drdf4j.lmdb.regret.enabled=true}. Knobs: {@code rdf4j.lmdb.regret.theme} (default
 * {@code MEDICAL_RECORDS}), {@code rdf4j.lmdb.regret.window} seconds (default 20), {@code rdf4j.lmdb.regret.rounds}
 * (default 3), {@code rdf4j.lmdb.regret.timeout} seconds per run (default 20), {@code rdf4j.lmdb.regret.output}
 * (default {@code target/strategy-regret-theme-<theme>.tsv}), {@code rdf4j.lmdb.regret.queries} (comma-separated query
 * indexes, default all), and {@code rdf4j.lmdb.regret.assert=true} to fail on the acceptance rules: no chosen strategy
 * above 1.5x the fastest, and {@code nestedLoop} chosen only when within 1.5x.
 */
@Isolated
@EnabledIfSystemProperty(named = "rdf4j.lmdb.regret.enabled", matches = "true")
class LmdbNativeThemeRegretHarnessIT {

	private static final double ACCEPTABLE_REGRET = 1.5D;

	@Test
	@Timeout(value = 6, unit = TimeUnit.HOURS)
	void measureEveryAdmittedStrategyOnTheThemeStore() throws Exception {
		Theme theme = Theme.valueOf(System.getProperty("rdf4j.lmdb.regret.theme", Theme.MEDICAL_RECORDS.name()));
		long windowNanos = TimeUnit.SECONDS.toNanos(Long.getLong("rdf4j.lmdb.regret.window", 20L));
		int rounds = Integer.getInteger("rdf4j.lmdb.regret.rounds", 3);
		int timeoutSeconds = Integer.getInteger("rdf4j.lmdb.regret.timeout", 20);
		Path output = Paths.get(System.getProperty("rdf4j.lmdb.regret.output",
				"target/strategy-regret-theme-" + theme.name().toLowerCase(Locale.ROOT) + ".tsv"));
		Files.createDirectories(output.toAbsolutePath().getParent());
		ThemeQueryBenchmark benchmark = new ThemeQueryBenchmark();
		benchmark.themeName = theme.name();
		benchmark.z_queryIndex = 0;
		System.setProperty(ThemeQueryBenchmark.WAIT_FOR_DIRECT_ADJACENCY_PROPERTY, "true");
		benchmark.setup();
		List<Timing> timings = new ArrayList<>();
		try {
			Field field = ThemeQueryBenchmark.class.getDeclaredField("repository");
			field.setAccessible(true);
			SailRepository repository = (SailRepository) field.get(benchmark);
			List<String> queries = ThemeQueryCatalog.queriesFor(theme);
			String selection = System.getProperty("rdf4j.lmdb.regret.queries", "");
			for (int index = 0; index < queries.size(); index++) {
				if (!selection.isEmpty() && !List.of(selection.split(",")).contains(Integer.toString(index))) {
					continue;
				}
				String name = "q" + index + " "
						+ ThemeQueryCatalog.benchmarkQueryFor(theme, index).getName().replace('\t', ' ');
				List<Timing> measured = LmdbNativeRegretHarness.measureQueryInterleaved(repository, name,
						"theme", theme.name().toLowerCase(Locale.ROOT), queries.get(index), windowNanos, rounds,
						timeoutSeconds);
				timings.addAll(measured);
				Files.write(output, LmdbNativeRegretHarness.render(timings), StandardCharsets.UTF_8);
				System.out.println(LmdbNativeRegretHarness.summary(measured));
			}
		} finally {
			benchmark.tearDown();
		}
		Files.write(output, LmdbNativeRegretHarness.render(timings), StandardCharsets.UTF_8);
		System.out.println(LmdbNativeRegretHarness.summary(timings));
		assertThat(timings).isNotEmpty();
		if (Boolean.getBoolean("rdf4j.lmdb.regret.assert")) {
			List<String> violations = new ArrayList<>();
			for (Regret regret : LmdbNativeRegretHarness.regrets(timings)) {
				if (regret.ratio() > ACCEPTABLE_REGRET) {
					violations.add(String.format(Locale.ROOT, "%s: chose %s at %.2fx the fastest %s",
							regret.decision().replace('\t', ' '), regret.chosen().id(), regret.ratio(),
							regret.fastest().id()));
				}
			}
			assertThat(violations).as("decisions above %.1fx regret", ACCEPTABLE_REGRET).isEmpty();
		}
	}
}
